INSERT INTO products (id, name, brand, category, tags, description, flavors, sizes, price, old_price, currency, in_stock, badge, featured, show_in_catalog, show_in_new, image, image_hover, href) VALUES
('lipo6-hers', 'LIPO6 HERS ULTRA CONCENTRATE', 'Nutrex Research', 'fat-burner', '{"Brûleur", "Femme", "Minceur"}', 'Lipo6 within an all - there''s a flame waiting to be kinders'' to pooth of passion and heat that ignites our purpose and sent us on a path towards greatness in life... and beyond.', '[{"name": "Non aromatisé", "color": "#8f8f8f"}]', '{"60 Liqui-Caps"}', 6500, 7500, 'DA', true, 'NOUVEAU', true, true, false, '/images/products/lipo6-hers.png', '/images/products/lipo6-hers.png', '#'),
('shilajit', 'SHILAJIT HIMALAYAN HEALTH', 'Applied Nutrition', 'peptide', '{"Santé", "Vitalité", "Minéraux"}', 'Shilajit de l''Himalaya pur, dosé à 30 000mg. Source naturelle riche en plus de 85 oligo-éléments et acide fulvique pour une vitalité optimale.', '[{"name": "Non aromatisé", "color": "#8f8f8f"}]', '{"90 Capsules"}', 7800, 8800, 'DA', true, 'PREMIUM', false, true, false, '/images/products/shilajit.png', '/images/products/shilajit.png', '#'),
('jumbo-hardcore', 'JUMBO HARDCORE', 'Scitec Nutrition', 'protein', '{"Gainer", "Masse", "Force"}', 'Formule gainer de masse hardcore contenant 7 sources de glucides et un complexe protéiné multi-sources, sans lactose ni gluten. Idéal pour les hardgainers.', '[{"name": "Chocolat", "color": "#3d1c02"}]', '{"5.35kg"}', 14500, 16000, 'DA', true, 'BEST-SELLER', true, true, false, '/images/products/jumbo-hardcore.png', '/images/products/jumbo-hardcore.png', '#'),
('tongkat-ali', 'TONGKAT ALI MALE PERFORMANCE', 'Applied Nutrition', 'sarms', '{"Performance", "Force", "Testo"}', 'Tongkat Ali de dosage maximal 1000mg avec AstraGin. Soutient la performance masculine, la libido, la force et le développement musculaire.', '[{"name": "Non aromatisé", "color": "#8f8f8f"}]', '{"60 Capsules"}', 8200, 9500, 'DA', true, 'POPULAIRE', true, true, false, '/images/products/tongkat-ali.png', '/images/products/tongkat-ali.png', '#'),
('ostrovit-creatine-watermelon', 'CREATINE MONOHYDRATE (Pastèque)', 'OstroVit', 'creatine', '{"Créatine", "Force", "Pastèque"}', 'Créatine monohydrate micronisée pure 200 Mesh au goût rafraîchissant de pastèque. Sans colorants ni sucres ajoutés.', '[{"name": "Pastèque", "color": "#f49da6"}]', '{"300g"}', 4200, 4900, 'DA', true, 'PROMO', false, true, false, '/images/products/ostrovit-creatine-watermelon.png', '/images/products/ostrovit-creatine-watermelon.png', '#'),
('iso-whey-zero-black-strawberry', 'ISO WHEY ZERO BLACK (Fraise)', 'BioTechUSA', 'protein', '{"Whey", "Isolat", "Fraise"}', 'Isolat de protéines de lactosérum de qualité anabolique avec 3g de créatine par portion, sans sucre ni gluten.', '[{"name": "Fraise", "color": "#e8a0a0"}]', '{"2.27kg"}', 12800, 14500, 'DA', true, 'BEST-SELLER', true, true, false, '/images/products/iso-whey-zero-black-strawberry.png', '/images/products/iso-whey-zero-black-strawberry.png', '#'),
('lipo6-hardcore', 'LIPO6 HARDCORE MAXIMUM STRENGTH', 'Nutrex Research', 'fat-burner', '{"Brûleur", "Thermosect", "Énergie"}', 'The path to greatness is often paved with sacrifice - which is why an many choose not to travel it. Brûleur de graisse thermogénique de force maximale.', '[{"name": "Non aromatisé", "color": "#8f8f8f"}]', '{"60 Capsules"}', 6800, 7800, 'DA', true, 'EXTRÊME', false, true, false, '/images/products/lipo6-hardcore.png', '/images/products/lipo6-hardcore.png', '#'),
('solid-mass', 'SOLID MASS PROTEIN DRINK', 'TREC', 'protein', '{"Gainer", "Masse", "Glucides"}', 'Solid Mass est un gainer de masse à base de concentré de protéines de lactosérum et de glucides, enrichi en L-Glutamine.', '[{"name": "Chocolat", "color": "#3d1c02"}]', '{"10kg"}', 19500, 22000, 'DA', true, 'NOUVEAU', false, true, true, '/images/products/solid-mass.png', '/images/products/solid-mass.png', '#'),
('critical-mass-banana', 'CRITICAL MASS ORIGINAL (Banane)', 'Applied Nutrition', 'protein', '{"Gainer", "Banane", "Calories"}', 'Critical Mass Original Formula est un gainer de masse hyper-calorique premium. Fournit 55g de protéines et 916 kcal par portion.', '[{"name": "Banane", "color": "#d6c04a"}]', '{"6kg"}', 15500, 17500, 'DA', true, 'GÉANT', true, true, false, '/images/products/critical-mass-banana.png', '/images/products/critical-mass-banana.png', '#'),
('extreme-fat-burner', 'EXTREME FAT BURNER', 'Exploramus Invenimus', 'fat-burner', '{"Brûleur", "Carnitine", "Thé Vert"}', 'Brûleur de graisse extrême formulé avec 1200mg de L-Tyrosine, 1000mg de L-Carnitine et 300mg d''extrait de Thé Vert. Goût pastèque.', '[{"name": "Pastèque", "color": "#f49da6"}]', '{"300g"}', 5900, 6800, 'DA', true, 'INTENSE', false, true, false, '/images/products/extreme-fat-burner.png', '/images/products/extreme-fat-burner.png', '#'),
('opti-men', 'OPTI-MEN ACTIVE MULTIVITAMIN', 'Optimum Nutrition', 'multivitamins', '{"Vitamines", "Santé", "Homme"}', 'Complément multivitaminé haut de gamme pour hommes actifs. Contient 36 ingrédients actifs pour soutenir le métabolisme et réduire la fatigue.', '[{"name": "Non aromatisé", "color": "#8f8f8f"}]', '{"90 Tablettes"}', 5500, 6200, 'DA', true, 'ESSENTIEL', true, true, false, '/images/products/opti-men.png', '/images/products/opti-men.png', '#'),
('life-pro-elektro', 'ELEKTRO INTENSE PRE-WORKOUT', 'Life Pro Nutrition', 'preworkout', '{"Pre-Workout", "Énergie", "Cola"}', 'Pré-workout ultra-concentré avec 3g de Bêta-Alanine, 1.5g de Taurine et 200mg de Caféine anhydre. Formule instantanée.', '[{"name": "Bubble Cola", "color": "#4a2c11"}]', '{"400g"}', 7200, 8200, 'DA', true, 'BOOST', false, true, false, '/images/products/life-pro-elektro.png', '/images/products/life-pro-elektro.png', '#'),
('citrulline-malate', 'CITRULLINE MALATE (Citron Vert)', 'BioTechUSA', 'preworkout', '{"Citrulline", "Pump", "Performance"}', 'L-Citrulline Malate pure sans sucre ni gluten. Optimise la congestion musculaire, la circulation et la force.', '[{"name": "Citron Vert", "color": "#b8d85a"}]', '{"300g"}', 5200, 5900, 'DA', true, 'PUMP', false, true, false, '/images/products/citrulline-malate.png', '/images/products/citrulline-malate.png', '#'),
('marine-collagen-mango', 'MARINE COLLAGEN (Mangue)', 'GOLDENBODY', 'peptide', '{"Collagène", "Soin", "Articulations"}', 'Collagène marin hydrolysé de qualité supérieure pour le soin de la peau, des os et des articulations. Goût Mangue.', '[{"name": "Mangue", "color": "#f4ab21"}]', '{"250g"}', 6800, 7800, 'DA', true, 'PEPTIDES', true, true, false, '/images/products/marine-collagen-mango.png', '/images/products/marine-collagen-mango.png', '#'),
('eaa-glutamine-mango', 'EAA + GLUTAMINE (Mangue)', 'Scitec Nutrition', 'bcaa', '{"EAA", "Acides Aminés", "Récupération"}', 'Combinaison d''acides aminés essentiels (EAA) et de L-Glutamine avec 4000mg de BCAA par portion. Sans sucres ajoutés.', '[{"name": "Mangue", "color": "#f4ab21"}]', '{"300g"}', 6400, 7200, 'DA', true, 'RECUP', false, true, false, '/images/products/eaa-glutamine-mango.png', '/images/products/eaa-glutamine-mango.png', '#'),
('muscle-pro', 'MUSCLE PRO PROTEIN', 'Scitec Nutrition', 'protein', '{"Whey", "Créatine", "Muscle"}', 'Préparation protéinée de haute qualité enrichie en créatine et acides aminés pour stimuler le gain de force et de volume.', '[{"name": "Fraise", "color": "#e8a0a0"}]', '{"2.5kg"}', 11500, 13000, 'DA', true, 'COMPLET', false, true, false, '/images/products/muscle-pro.png', '/images/products/muscle-pro.png', '#'),
('pure-whey-chocolate', 'PURE WHEY (Chocolat)', 'GOLDENBODY', 'protein', '{"Whey", "Chocolat", "WPC"}', 'Complexe multi-protéines haut de gamme (WPC, WPI, WPH) enrichi en enzymes digestives pour une assimilation parfaite. Goût chocolat.', '[{"name": "Chocolat", "color": "#3d1c02"}]', '{"1kg"}', 7500, 8500, 'DA', true, 'PROMO', true, true, false, '/images/products/pure-whey-chocolate.png', '/images/products/pure-whey-chocolate.png', '#'),
('body-fuel-preworkout', 'BODY FUEL PRE-WORKOUT', 'Applied Nutrition', 'preworkout', '{"Pre-Workout", "Énergie", "Performance"}', 'Body Fuel Pre-Workout offre une performance optimisée avec un boost d''énergie et de focus intense. Formule explosive.', '[{"name": "Tropical", "color": "#f6c866"}]', '{"300g"}', 6900, 7800, 'DA', true, 'NOUVEAU', false, true, true, '/images/products/body-fuel-preworkout.png', '/images/products/body-fuel-preworkout.png', '#'),
('iso-whey-zero-black-mango', 'ISO WHEY ZERO BLACK (Mangue)', 'BioTechUSA', 'protein', '{"Whey", "Isolat", "Mangue"}', 'Isolat de lactosérum sans créatine, sans sucre ni gluten. Formulé pour soutenir le maintien et le développement de la masse musculaire sèche.', '[{"name": "Mangue", "color": "#f4ab21"}]', '{"900g"}', 5800, 6500, 'DA', true, 'LÉGER', false, true, false, '/images/products/iso-whey-zero-black-mango.png', '/images/products/iso-whey-zero-black-mango.png', '#'),
('yohimbine-liquid', 'YOHIMBINE LIQUIDE', 'Exploramus Invenimus', 'sarms', '{"Sarms", "Sèche", "Graisses"}', 'Yohimbine liquide stérile de qualité pharmaceutique dosée à 750mg. Idéal pour cibler et éliminer les tissus adipeux les plus tenaces.', '[{"name": "Non aromatisé", "color": "#8f8f8f"}]', '{"180ml"}', 4800, 5500, 'DA', true, 'SÈCHE', true, true, false, '/images/products/yohimbine-liquid.png', '/images/products/yohimbine-liquid.png', '#'),
('lipo6-stim-free', 'LIPO6 STIM-FREE FAT LOSS', 'Nutrex Research', 'fat-burner', '{"Brûleur", "Sans Caféine", "Sain"}', 'Every step you take on your journey is an opportunity. The road isn''t always smooth - but it is through these challenges that we build a lasting legacy. Formule de perte de poids sans stimulants.', '[{"name": "Non aromatisé", "color": "#8f8f8f"}]', '{"60 Capsules"}', 6200, 7200, 'DA', true, 'SANS-STIM', false, true, false, '/images/products/lipo6-stim-free.png', '/images/products/lipo6-stim-free.png', '#'),
('applied-creatine-500g', 'CREATINE MONOHYDRATE MICRONIZED', 'Applied Nutrition', 'creatine', '{"Créatine", "Micronisée", "Force"}', 'Poudre de créatine monohydrate micronisée pure à 100% avec le logo Informed Sport. Améliore la force et la puissance athlétique.', '[{"name": "Non aromatisé", "color": "#8f8f8f"}]', '{"500g"}', 6500, 7500, 'DA', true, 'QUALITÉ', true, true, false, '/images/products/applied-creatine-500g.png', '/images/products/applied-creatine-500g.png', '#'),
('trec-casein-protein', 'CASEIN PROTEIN (Chocolat)', 'TREC', 'protein', '{"Caséine", "Nuit", "Récupération"}', 'Protéine de caséine micellaire de qualité supérieure pour une libération prolongée d''acides aminés pendant le sommeil. Goût Chocolat.', '[{"name": "Chocolat", "color": "#3d1c02"}]', '{"1kg"}', 8500, 9800, 'DA', true, 'NUIT', false, true, false, '/images/products/trec-casein-protein.png', '/images/products/trec-casein-protein.png', '#'),
