('iso-whey-platinum', 'ISO WHEY PLATINUM', 'BioTechUSA', 'protein', '{"Whey", "Créatine", "Platinum"}', 'Mélange de whey protéine platinum enrichi en créatine et en L-Glutamine pour maximiser l''anabolisme musculaire.', '[{"name": "Chocolat", "color": "#3d1c02"}]', '{"900g"}', 7200, 8200, 'DA', true, 'PLATINUM', false, true, false, '/images/products/iso-whey-platinum.png', '/images/products/iso-whey-platinum.png', '#'),
('scitec-100-whey-professional', '100% WHEY PROTEIN PROFESSIONAL', 'Scitec Nutrition', 'protein', '{"Whey", "Pistache", "WPC"}', 'Boisson protéinée premium à base de concentré et d''isolat de whey protéine avec acides aminés ajoutés. Sans gluten.', '[{"name": "Pistache Chocolat Blanc", "color": "#b2d3a8"}]', '{"2.35kg"}', 12500, 14000, 'DA', true, 'EXCLUSIF', true, true, false, '/images/products/scitec-100-whey-professional.png', '/images/products/scitec-100-whey-professional.png', '#'),
('mega-creatine', 'MEGA CREATINE (Creapure)', 'BioTechUSA', 'creatine', '{"Créatine", "Mega", "Creapure"}', 'Créatine monohydrate de qualité Creapure dosée à 3400mg par jour pour augmenter la puissance musculaire lors d''efforts courts.', '[{"name": "Non aromatisé", "color": "#8f8f8f"}]', '{"306g"}', 4900, 5500, 'DA', true, 'CREAPURE', false, true, false, '/images/products/mega-creatine.png', '/images/products/mega-creatine.png', '#'),
('life-pro-creatine', 'CREATINE MONOHYDRATE Creapure', 'Life Pro Nutrition', 'creatine', '{"Créatine", "Creapure", "Pure"}', 'Créatine 100% Creapure sans additifs, offrant une solubilité et une biodisponibilité optimales pour booster vos performances physiques.', '[{"name": "Non aromatisé", "color": "#8f8f8f"}]', '{"250g"}', 4500, 5200, 'DA', true, 'CREAPURE', false, true, false, '/images/products/life-pro-creatine.png', '/images/products/life-pro-creatine.png', '#'),
