('usn-creapure-creatine', 'USN CREAPURE CREATINE', 'USN', 'creatine', '{"Créatine", "Creapure", "Force"}', 'Créatine monohydrate 100% Creapure de marque USN. Conçue pour optimiser la force musculaire explosive et l''endurance.', '[{"name": "Non aromatisé", "color": "#8f8f8f"}]', '{"170g"}', 4200, 4900, 'DA', true, 'CONGESTION', false, true, false, '/images/products/usn-creapure-creatine.png', '/images/products/usn-creapure-creatine.png', '#'),
('iso-whey-zero-salted-caramel', 'ISO WHEY ZERO (Caramel Salé)', 'BioTechUSA', 'protein', '{"Whey", "Isolat", "Caramel"}', 'Isolat de protéines de lactosérum de qualité premium avec BCAA et L-Glutamine, goût exquis de caramel salé.', '[{"name": "Caramel Salé", "color": "#d6a45c"}]', '{"2.27kg"}', 12500, 14000, 'DA', true, 'DELICIEUX', false, true, false, '/images/products/iso-whey-zero-salted-caramel.png', '/images/products/iso-whey-zero-salted-caramel.png', '#'),
