INSERT INTO products (id, name, brand, category, tags, description, flavors, sizes, price, old_price, currency, in_stock, badge, featured, show_in_catalog, show_in_new, image, image_hover, href) VALUES
('ostrovit-marine-collagen', 'MARINE COLLAGEN (Cassis)', 'OstroVit', 'peptide', '{"Collagène", "Marin", "Peau"}', 'Collagène marin de type I OstroVit NUTRICOSMETICS à la saveur cassis. 200g de collagène pur pour la santé de la peau, des articulations et des cheveux.', '[{"name": "Black Currant", "color": "#4a1d6e"}]', '{"200g"}', 4900, 5500, 'DA', true, 'NOUVEAU', false, true, false, '/images/products/ostrovit-marine-collagen.png', '/images/products/ostrovit-marine-collagen.png', '#'),
('lipo6-hardcore', 'LIPO-6 HARDCORE', 'Nutrex Research', 'fat-burner', '{"Brûleur", "Hardcore", "Fat Burner"}', 'LIPO-6 HARDCORE de Nutrex Research, le brûleur de graisse maximum avec 60 capsules. Formule avancée pour une perte de poids rapide et efficace.', '[{"name": "Non aromatisé", "color": "#8f8f8f"}]', '{"60 Capsules"}', 3900, 4500, 'DA', true, 'HARDCORE', false, true, false, '/images/products/lipo6-hardcore.png', '/images/products/lipo6-hardcore.png', '#'),
('scitec-jumbo-green', 'JUMBO (Fraise)', 'Scitec Nutrition', 'protein', '{"Gainer", "Masse", "Protéine"}', 'JUMBO Scitec Nutrition, boisson protéinée en poudre avec 7 glucides, matrix musculaire, complexe énergétique et acides aminés. 6600g pour 30 servings.', '[{"name": "Fraise", "color": "#e8a0a0"}]', '{"6600g"}', 14900, 16500, 'DA', true, 'POPULAIRE', true, true, false, '/images/products/scitec-jumbo-green.png', '/images/products/scitec-jumbo-green.png', '#'),
('biotech-l-carnitine-liquid', 'L-CARNITINE 100.000 LIQUID (Cerise)', 'BioTechUSA', 'fat-burner', '{"L-Carnitine", "Liquide", "Brûleur"}', 'BioTechUSA L-CARNITINE 100.000 LIQUID à la cerise. 2000mg de L-Carnitine par serving avec extrait de thé vert et vitamines. Sans sucre, 500ml (50 servings).', '[{"name": "Cerise", "color": "#c0392b"}]', '{"500ml"}', 3200, 3800, 'DA', true, null, false, true, false, '/images/products/biotech-l-carnitine-liquid.png', '/images/products/biotech-l-carnitine-liquid.png', '#'),
